fix:
Strictly separate the data plane (the actuator that executes deployments) from the control plane (the dynamic configuration representing scheduling policy).
```rust
struct RolloutSystem {
    policy_client: PolicyServiceClient,
}

impl RolloutSystem {
    pub fn deploy(&self, image: Image) {
        for group in self.machine_groups() {
            self.install(group, image);
            let wait_duration = self.policy_client.get_next_wait_interval();
            std::thread::sleep(wait_duration);
        }
    }
}
